//! This service's own strings: a typed `leptos_i18n` catalogue generated by
//! `build.rs` from `locales/<code>.json`, read in ui-lib's one
//! [`language_signal`] — the same signal the library's strings read, so a
//! page never mixes the two (copied from `ui-lab`'s gallery, task 032's
//! pattern).
//!
//! Take [`strings`] once, then read each string inside a reactive closure,
//! so a language switch re-renders that text alone:
//!
//! ```ignore
//! let t = strings();
//! view! { <h1>{move || td_string!(t.locale(), empty_title)}</h1> }
//! ```

#[allow(missing_docs, unused, clippy::all, clippy::pedantic)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/i18n/mod.rs"));
}

pub(crate) use generated::i18n::Locale;

use leptos::prelude::*;
use palicanon_ui_lib::{Language, language_signal};

/// This service's catalogue, bound to [`language_signal`]: copy it into
/// closures, read [`Strings::locale`] inside them.
#[derive(Clone, Copy, Debug)]
pub(crate) struct Strings(RwSignal<Language>);

impl Strings {
    /// The current language's catalogue locale. Tracked: a closure reading
    /// it runs again when the language changes.
    pub(crate) fn locale(self) -> Locale {
        Locale::from(self.0.get())
    }
}

/// This service's strings, in the language of [`language_signal`].
pub(crate) fn strings() -> Strings {
    Strings(language_signal())
}

impl From<Language> for Locale {
    /// Exhaustive: a new [`Language`] does not build until this service
    /// has its strings (and a `locales/<code>.json`).
    fn from(language: Language) -> Self {
        match language {
            Language::En => Locale::en,
            Language::Fr => Locale::fr,
            Language::Vi => Locale::vi,
        }
    }
}

#[cfg(test)]
mod tests {
    use leptos_i18n::td_string;

    use super::*;

    #[test]
    fn every_language_reads_its_own_strings() {
        let labels: Vec<&str> = Language::ALL
            .into_iter()
            .map(|language| td_string!(Locale::from(language), nav_search))
            .collect();
        assert_eq!(labels, ["Search", "Recherche", "Tìm kiếm"]);
    }

    #[test]
    fn strings_follow_the_language_signal() {
        Owner::new().with(|| {
            let t = strings();
            let label = Signal::derive(move || td_string!(t.locale(), nav_search));
            assert_eq!(label.get(), "Search");
            language_signal().set(Language::Fr);
            assert_eq!(label.get(), "Recherche", "switched live");
        });
    }

    /// Keys whose French or Vietnamese value is, rightly, the English
    /// word: "Collection", "Site" (today's site's `footer.nav`) and
    /// "passage(s)" (its results count) are French as well. "404" is a
    /// numeral, "Anattā — PaliCanon" is a title, and "Anattā" is a Pāli
    /// term in all languages.
    const SAME_AS_ENGLISH: [(&str, &str); 10] = [
        ("fr", "collection_label"),
        ("fr", "notfound_eyebrow"),
        ("fr", "notfound_head_title"),
        ("fr", "notfound_title"),
        ("fr", "pages_nav"),
        ("fr", "results_label"),
        ("fr", "results_one"),
        ("vi", "notfound_eyebrow"),
        ("vi", "notfound_head_title"),
        ("vi", "notfound_title"),
    ];

    fn catalogue(json: &str) -> serde_json::Map<String, serde_json::Value> {
        serde_json::from_str(json).expect("a flat JSON object")
    }

    /// Every English key exists in French and Vietnamese, each translated:
    /// a missing key would fall back to English in that language's UI
    /// (round 3 user check: "Try different words, or fewer of them." seen
    /// in a French UI).
    #[test]
    fn every_key_is_translated_in_every_language() {
        let en = catalogue(include_str!("../locales/en.json"));
        for (code, json) in [
            ("fr", include_str!("../locales/fr.json")),
            ("vi", include_str!("../locales/vi.json")),
        ] {
            let other = catalogue(json);
            for (key, english) in &en {
                let value = other.get(key);
                assert!(value.is_some(), "{code}.json lacks {key}");
                if !SAME_AS_ENGLISH.contains(&(code, key.as_str())) {
                    assert_ne!(value, Some(english), "{code}.json: {key} is English");
                }
            }
            assert_eq!(other.len(), en.len(), "{code}.json has extra keys");
        }
    }
}
